; --- αρχή κάθε κλάσης εδάφους, ως ΜΕΤΑΤΟΠΙΣΗ από την αρχή
;     του μπλοκ. Πραγματική διεύθυνση = base + tile_base[class].
;     tile_base[class] + variant*TILE_SZ ---
tile_base:
    dw #4C8C   ; 0 ground      4 παραλλαγές
    dw #4D8C   ; 1 dust        4 παραλλαγές
    dw #4E8C   ; 2 rock        4 παραλλαγές
    dw #4F8C   ; 3 mountain   16 autotile
    dw #538C   ; 4 water      16 autotile
    dw #578C   ; 5 deepwater   4 παραλλαγές
    dw #588C   ; 6 crater      2 παραλλαγές
    dw #590C   ; 7 foundation  2 παραλλαγές

; --- παραλλαγές ανά κλάση εδάφους ---
; Όλα είναι δυνάμεις του 2, οπότε:  variant AND (count-1)
; Χωρίς αυτό το mask, decor 2-3 σε crater/foundation δείχνει
; στα tiles της ΕΠΟΜΕΝΗΣ κλάσης.
tile_variants:
    db 4,4,4,16,16,4,2,2
    ; ground, dust, rock, mountain, water, deepwater, crater, foundation

; --- planet_pens + planet*4 -> FW για τα pens 7, 11, 12, 14 ---
planet_pens:
    db  15,  3, 25, 10   ; 0 desert  άμμος και σκουριά
    db  14,  2, 20, 22   ; 1 ice     πάγος και χιόνι
    db  12,  9, 21, 19   ; 2 storm   λάσπη και βρύα
    db  10,  4, 14,  2   ; 3 barren  γυμνός βράχος

structures:

; solar_s — 8 x 16 pixels, mask+data, 128 bytes
solar_s:
